//! Renders the model as Rust source.

use std::collections::BTreeSet;
use std::fmt::Write as _;

use proc_macro2::{Ident, Literal, Span, TokenStream};
use quote::quote;

use heck::ToUpperCamelCase;

use crate::model::{
    Body, EnumDef, Export, ExportKind, Field, Merchant, Model, OperationDef, Role, StructDef, Ty,
};

pub const HEADER: &str = "// @generated by `cargo xtask codegen` from schema/repay-v1.json,\n\
                          // schema/repay-v1-internal.json and schema/overrides.toml.\n\
                          // Do not edit by hand.\n\n";

/// Types from `crate::types` that the model names.
const RUNTIME_TYPES: &[&str] = &[
    "AchTokenKey",
    "Amount",
    "AmountString",
    "AuditKey",
    "AuthFormId",
    "CardTokenKey",
    "ContractKey",
    "CustomFieldId",
    "CustomerKey",
    "ExpDate",
    "MerchantId",
    "OrgId",
    "RuleId",
    "TemplateId",
    "TransactionId",
];

/// The generated files, as (file name, contents).
pub fn render(model: &Model) -> Vec<(&'static str, String)> {
    vec![
        ("enums.rs", enums(&model.enums)),
        ("models.rs", models(model)),
        ("operations.rs", operations(&model.operations)),
    ]
}

fn file(tokens: TokenStream) -> String {
    let parsed: syn::File = syn::parse2(tokens).expect("generated code parses");
    let code = prettyplease::unparse(&parsed);
    // Separate top-level items with a blank line.
    let code = code
        .replace("\n}\n", "\n}\n\n")
        .replace(";\n///", ";\n\n///");
    format!("{HEADER}{}\n", code.trim_end_matches('\n'))
}

fn ident(name: &str) -> Ident {
    Ident::new(name, Span::call_site())
}

/// A field identifier, raw if it is a keyword (`type` -> `r#type`).
fn field_ident(name: &str) -> Ident {
    if syn::parse_str::<Ident>(name).is_ok() {
        ident(name)
    } else {
        Ident::new_raw(name, Span::call_site())
    }
}

/// `#[doc]` attributes.
fn docs(doc: Option<&str>) -> TokenStream {
    let lines = doc_lines(doc);
    quote!(#(#[doc = #lines])*)
}

fn doc_lines(doc: Option<&str>) -> Vec<String> {
    doc.map(|d| d.lines().map(|l| format!(" {}", escape_doc(l))).collect())
        .unwrap_or_default()
}

/// Escapes text that rustdoc would read as markup, outside `code` spans, and
/// makes bare URLs links.
fn escape_doc(line: &str) -> String {
    let mut out = String::with_capacity(line.len());
    let mut code = false;
    for word in line.split_inclusive(' ') {
        let bare = word.trim_end();
        if !code && (bare.starts_with("http://") || bare.starts_with("https://")) {
            let url = bare.trim_end_matches(['.', ',', ')']);
            out.push('<');
            out.push_str(url);
            out.push('>');
            out.push_str(&word[url.len()..]);
            continue;
        }
        for c in word.chars() {
            if c == '`' {
                code = !code;
            } else if !code && matches!(c, '<' | '>' | '[' | ']' | '*' | '_' | '#' | '\\') {
                out.push('\\');
            }
            out.push(c);
        }
    }
    out
}

/// The type in `models.rs`, where everything it names is imported.
fn rust_type(ty: &Ty) -> TokenStream {
    match ty {
        Ty::String => quote!(String),
        Ty::Bool => quote!(bool),
        Ty::I32 => quote!(i32),
        Ty::I64 => quote!(i64),
        Ty::F64 => quote!(f64),
        Ty::DateTime => quote!(DateTime),
        Ty::Json => quote!(Json),
        Ty::Map => quote!(BTreeMap<String, String>),
        Ty::Vec(inner) => {
            let inner = rust_type(inner);
            quote!(Vec<#inner>)
        }
        Ty::Named(name) => {
            let name = ident(name);
            quote!(#name)
        }
    }
}

/// The type in the operation table, with full paths so that the macro expands
/// anywhere.
fn qualified_type(ty: &Ty) -> String {
    match ty {
        Ty::String => "::std::string::String".into(),
        Ty::Bool => "bool".into(),
        Ty::I32 => "i32".into(),
        Ty::I64 => "i64".into(),
        Ty::F64 => "f64".into(),
        Ty::DateTime => "$crate::types::DateTime".into(),
        Ty::Json => "$crate::types::Json".into(),
        Ty::Map => {
            "::std::collections::BTreeMap<::std::string::String, ::std::string::String>".into()
        }
        Ty::Vec(inner) => format!("::std::vec::Vec<{}>", qualified_type(inner)),
        Ty::Named(name) if RUNTIME_TYPES.contains(&name.as_str()) => {
            format!("$crate::types::{name}")
        }
        Ty::Named(name) => format!("$crate::schema::{name}"),
    }
}

fn walk_types<'a>(ty: &'a Ty, out: &mut BTreeSet<&'a str>) {
    match ty {
        Ty::Vec(inner) => walk_types(inner, out),
        Ty::Named(name) if RUNTIME_TYPES.contains(&name.as_str()) => {
            out.insert(name);
        }
        Ty::DateTime => {
            out.insert("DateTime");
        }
        Ty::Json => {
            out.insert("Json");
        }
        _ => {}
    }
}

fn enums(enums: &[EnumDef]) -> String {
    let mut out = String::from(HEADER);
    out.push_str("use crate::macros::string_enum;\n");
    for def in enums {
        let used_by: Vec<String> = def.used_by.iter().map(|p| format!("`{p}`")).collect();
        write!(
            out,
            "\nstring_enum! {{\n    /// Values of {}.\n    pub enum {} {{\n",
            used_by.join(", "),
            def.name
        )
        .unwrap();
        for variant in &def.variants {
            writeln!(out, "        {} = {:?},", variant.name, variant.value).unwrap();
        }
        out.push_str("    }\n}\n");
    }
    out
}

fn models(model: &Model) -> String {
    let mut runtime = BTreeSet::new();
    let mut map = false;
    for field in model.structs.iter().flat_map(|s| &s.fields) {
        walk_types(&field.ty, &mut runtime);
        map |= matches!(field.ty, Ty::Map) || field.ty == Ty::Vec(Box::new(Ty::Map));
    }
    let runtime = runtime.into_iter().map(ident);
    let map = map.then(|| {
        quote!(
            use std::collections::BTreeMap;
        )
    });
    let structs = model.structs.iter().map(struct_def);
    let sensitive = &model.sensitive;
    file(quote! {
        #map

        use bon::Builder;
        use serde::{Deserialize, Serialize};

        use crate::Model;
        use crate::types::{#(#runtime),*};
        #[allow(unused_imports)]
        use super::*;

        /// Properties whose values are secret, which logs redact.
        #[doc(hidden)]
        pub const SENSITIVE_FIELDS: &[&str] = &[#(#sensitive),*];

        #(#structs)*
    })
}

fn struct_def(def: &StructDef) -> TokenStream {
    let name = ident(&def.name);
    let doc = docs(def.doc.as_deref());
    let origin = (def.origin != def.name).then(|| {
        let line = format!(" Spec: `{}`", def.origin);
        let gap = def.doc.is_some().then(|| quote!(#[doc = ""]));
        quote!(#gap #[doc = #line])
    });
    let derives = match def.role {
        Role::Request => quote!(#[derive(Clone, PartialEq, Serialize, Model, Builder)]),
        Role::Response => quote!(#[derive(Clone, PartialEq, Default, Deserialize, Model)]),
        Role::Both => quote!(#[derive(Clone, PartialEq, Serialize, Deserialize, Model, Builder)]),
    };
    let builder = def
        .role
        .serializes()
        .then(|| quote!(#[builder(on(String, into))]));
    let fields = def.fields.iter().map(|f| field(f, def.role));
    quote! {
        #doc
        #origin
        #derives
        #builder
        #[non_exhaustive]
        pub struct #name {
            #(#fields)*
        }
    }
}

fn field(field: &Field, role: Role) -> TokenStream {
    let name = field_ident(&field.name);
    let doc = docs(field.doc.as_deref());
    let ty = rust_type(&field.ty);
    let (ty, serde, builder) = match (role, field.ty.is_vec(), field.required) {
        (Role::Response, _, _) => (quote!(Option<#ty>), None, None),
        (_, true, true) => (ty, None, None),
        (_, true, false) => (
            ty,
            Some(quote!(#[serde(default, skip_serializing_if = "Vec::is_empty")])),
            Some(quote!(#[builder(default)])),
        ),
        (_, false, true) => (ty, None, None),
        (_, false, false) => (
            quote!(Option<#ty>),
            Some(quote!(#[serde(skip_serializing_if = "Option::is_none")])),
            None,
        ),
    };
    let repay = repay_attr(field);
    quote! {
        #doc
        #serde
        #builder
        #repay
        pub #name: #ty,
    }
}

fn repay_attr(field: &Field) -> Option<TokenStream> {
    let f = &field.facets;
    let mut args = Vec::new();
    if field.sensitive {
        args.push(quote!(sensitive));
    }
    if let Some(n) = f.min_length {
        let n = Literal::u64_unsuffixed(n);
        args.push(quote!(min_length = #n));
    }
    if let Some(n) = f.max_length {
        let n = Literal::u64_unsuffixed(n);
        args.push(quote!(max_length = #n));
    }
    if let Some(min) = &f.min {
        args.push(quote!(min = #min));
    }
    if let Some(max) = &f.max {
        args.push(quote!(max = #max));
    }
    if let Some(rule) = &f.rule {
        args.push(quote!(rule = #rule));
    }
    (!args.is_empty()).then(|| quote!(#[repay(#(#args),*)]))
}

/// The `operation_table!` callback macro. Written as text: `prettyplease` does not
/// lay out macro bodies.
fn operations(operations: &[OperationDef]) -> String {
    let mut out = String::from(HEADER);
    out.push_str(
        "/// Invokes `$callback!` with every operation, grouped by client resource.\n\
         ///\n\
         /// Every entry has the same keys in the same order, and optional parts are\n\
         /// bracketed lists of zero or one item. Types are written with full paths, so\n\
         /// the expansion compiles in any module.\n\
         macro_rules! operation_table {\n    \
         ($callback:ident) => {\n        \
         $callback! {\n",
    );
    let mut resources: Vec<&str> = operations.iter().map(|o| o.resource.as_str()).collect();
    resources.dedup();
    for resource in resources {
        let handle = resource.to_upper_camel_case();
        writeln!(out, "            {resource} => {handle} {{").unwrap();
        for op in operations.iter().filter(|o| o.resource == resource) {
            operation(&mut out, op);
        }
        out.push_str("            }\n");
    }
    out.push_str(
        "        }\n    \
         };\n\
         }\n\n\
         pub(crate) use operation_table;\n",
    );
    out
}

fn operation(out: &mut String, op: &OperationDef) {
    const INDENT: &str = "                ";
    for line in doc_lines(op.doc.as_deref()) {
        writeln!(out, "{INDENT}///{}", line.trim_end()).unwrap();
    }
    let name = op.method.to_upper_camel_case();
    writeln!(out, "{INDENT}{} => {name} {{", op.method).unwrap();
    let key = |out: &mut String, key: &str, value: &str| {
        writeln!(out, "{INDENT}    {key}: {value},").unwrap();
    };
    key(out, "id", &format!("{:?}", op.id));
    key(out, "method", &op.http_method);
    key(out, "path", &format!("{:?}", op.path));

    // Parameters, one per line with their docs, at `depth` levels inside the entry.
    let params = |params: Vec<(Option<&str>, String)>, depth: usize| {
        if params.is_empty() {
            return "{}".to_owned();
        }
        let inner = format!("{INDENT}{}", "    ".repeat(depth + 1));
        let mut s = String::from("{\n");
        for (doc, param) in params {
            for line in doc_lines(doc) {
                writeln!(s, "{inner}///{}", line.trim_end()).unwrap();
            }
            writeln!(s, "{inner}{param},").unwrap();
        }
        write!(s, "{INDENT}{}}}", "    ".repeat(depth)).unwrap();
        s
    };
    let path_params = op
        .path_params
        .iter()
        .map(|p| {
            let param = format!("{}: {} = {:?}", p.field, qualified_type(&p.ty), p.wire);
            (p.doc.as_deref(), param)
        })
        .collect();
    key(out, "path_params", &params(path_params, 1));
    let query = if op.query.is_empty() {
        "[]".to_owned()
    } else {
        let fields = op
            .query
            .iter()
            .map(|q| {
                let multi = if q.multi { " multi" } else { "" };
                let param = format!(
                    "{}: {} = {:?}{multi}",
                    q.field,
                    qualified_type(&q.ty),
                    q.wire
                );
                (q.doc.as_deref(), param)
            })
            .collect();
        format!("[{name}Params {}]", params(fields, 1))
    };
    key(out, "query", &query);
    let body = match &op.body {
        Body::None => "[]".to_owned(),
        Body::Json(ty) => format!("[json {}]", qualified_type(ty)),
        Body::Multipart => "[multipart]".to_owned(),
    };
    key(out, "body", &body);
    let merchant = match op.merchant {
        Merchant::None => "none",
        Merchant::Optional => "optional",
        Merchant::Required => "required",
    };
    key(out, "merchant", merchant);
    let response = match &op.response {
        _ if op.download => "download".to_owned(),
        Some(ty) => format!("json {}", qualified_type(ty)),
        None => "empty".to_owned(),
    };
    key(out, "response", &response);
    let export = match &op.export {
        None => "[]".to_owned(),
        Some(Export { kind, wire }) => {
            // The name of the client method that returns the file.
            let (kind, method) = match kind {
                ExportKind::Format => ("format", format!("{}_export", op.method)),
                ExportKind::Pdf => ("pdf", format!("{}_pdf", op.method)),
            };
            format!("[{kind} {wire:?} {method}]")
        }
    };
    key(out, "export", &export);
    key(out, "deprecated", &op.deprecated.to_string());
    writeln!(out, "{INDENT}}}").unwrap();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn escapes_markup_outside_code() {
        assert_eq!(
            escape_doc("a_b [x] `c_d` <e> see https://example.com/a_b."),
            r"a\_b \[x\] `c_d` \<e\> see <https://example.com/a_b>."
        );
    }

    #[test]
    fn qualifies_table_types() {
        assert_eq!(
            qualified_type(&Ty::Vec(Box::new(Ty::Named("TransactionId".into())))),
            "::std::vec::Vec<$crate::types::TransactionId>"
        );
        assert_eq!(
            qualified_type(&Ty::Named("CardSaleRequest".into())),
            "$crate::schema::CardSaleRequest"
        );
    }
}
